self.EXB_DATA = {"lib":{"pratt.exb":"// pratt.exb — a Pratt (top-down operator precedence) parser toolkit.\n//\n//   let pratt = require(\"pratt\")\n//   let spec = {\n//     prefix: { NUM: fn(p, t) { return {type: \"num\", value: num(t.text)} } },\n//     infix:  { PLUS: pratt.binary(10, false) }\n//   }\n//   let ast = pratt.parser(lexer.tokenize(src), spec).parse(0)\n//\n// prefix rules  : fn(p, token)        -> node\n// infix rules   : {prec: n, fn: fn(p, left, token) -> node}\n// Tokens are looked up by their `type`; name operator rules after the operator\n// itself (lexer rule [\"+\", \"\\\\+\"]) and the spec tables read naturally.\n// The parser object `p` offers: peek() next() check(type) match(type)\n// expect(type, msg) parse(prec) at_end() and fail(msg).\n\nfn parser(tokens, spec) {\n  let st = {pos: 0}\n  let p = {}\n\n  p.peek = fn() { return tokens[st.pos] }\n  p.at_end = fn() { return tokens[st.pos].type == \"EOF\" }\n  p.next = fn() {\n    let t = tokens[st.pos]\n    if t.type != \"EOF\" { st.pos += 1 }\n    return t\n  }\n  p.check = fn(type) { return tokens[st.pos].type == type }\n  p.match = fn(type) {\n    if tokens[st.pos].type == type {\n      st.pos += 1\n      return true\n    }\n    return false\n  }\n  p.fail = fn(msg) {\n    let t = tokens[st.pos]\n    let near = t.text\n    if t.type == \"EOF\" { near = \"end of input\" }\n    error(format(\"Parse error at %d:%d: %s (near '%s')\", t.line, t.col, msg, near))\n  }\n  p.expect = fn(type, msg) {\n    if tokens[st.pos].type == type {\n      return p.next()\n    }\n    if msg == nil { msg = \"expected \" + type }\n    p.fail(msg)\n  }\n  p.parse = fn(prec) {\n    let t = p.next()\n    let pre = spec.prefix[t.type]\n    if pre == nil {\n      st.pos -= 1\n      p.fail(\"unexpected token \" + t.type)\n    }\n    let left = pre(p, t)\n    while true {\n      let nt = tokens[st.pos]\n      let rule = spec.infix[nt.type]\n      if rule == nil { break }\n      if rule.prec <= prec { break }\n      p.next()\n      left = rule.fn(p, left, nt)\n    }\n    return left\n  }\n  return p\n}\n\n// Ready-made rule builders ---------------------------------------------------\n\nfn binary(prec, right_assoc) {\n  return {prec: prec, fn: fn(p, left, t) {\n    let rbp = prec\n    if right_assoc { rbp = prec - 1 }\n    return {type: \"binary\", op: t.text, left: left, right: p.parse(rbp)}\n  }}\n}\n\nfn postfix(prec) {\n  return {prec: prec, fn: fn(p, left, t) {\n    return {type: \"postfix\", op: t.text, operand: left}\n  }}\n}\n\nfn unary(prec) {\n  return fn(p, t) { return {type: \"unary\", op: t.text, operand: p.parse(prec)} }\n}\n\n// Repeatedly parse items separated by `sep` until `close` (consumed).\nfn separated(p, sep, close) {\n  let items = []\n  if p.match(close) { return items }\n  while true {\n    items.push(p.parse(0))\n    if p.match(sep) { continue }\n    p.expect(close, nil)\n    break\n  }\n  return items\n}\n\nreturn {parser: parser, binary: binary, postfix: postfix, unary: unary, separated: separated}\n","pretty.exb":"// pretty.exb — render any EXBIN value as an indented tree (handy for ASTs).\nfn tree(v, indent) {\n  if indent == nil { indent = 0 }\n  let pad = \"  \".repeat(indent)\n  let t = type(v)\n  if t == \"map\" {\n    if v.len == 0 { return \"{}\" }\n    let out = \"{\\n\"\n    for k in v.keys() {\n      out += pad + \"  \" + str(k) + \": \" + tree(v[k], indent + 1) + \"\\n\"\n    }\n    return out + pad + \"}\"\n  }\n  if t == \"list\" {\n    if v.len == 0 { return \"[]\" }\n    let out = \"[\\n\"\n    for x in v { out += pad + \"  \" + tree(x, indent + 1) + \"\\n\" }\n    return out + pad + \"]\"\n  }\n  return repr(v)\n}\n\n// One-line s-expression form: {type:\"binary\", ...} -> (binary + a b)\nfn sexpr(v) {\n  let t = type(v)\n  if t == \"map\" {\n    let parts = []\n    for k in v.keys() {\n      if k == \"type\" { continue }\n      parts.push(sexpr(v[k]))\n    }\n    let head = v.type\n    if head == nil { head = \"map\" }\n    let out = \"(\" + str(head)\n    if parts.len > 0 { out += \" \" + parts.join(\" \") }\n    return out + \")\"\n  }\n  if t == \"list\" { return \"[\" + v.map(sexpr).join(\" \") + \"]\" }\n  return str(v)\n}\n\nreturn {tree: tree, sexpr: sexpr}\n"},"examples":[{"name":"hello.exb","title":"مرحباً — جولة سريعة","code":"// EXBIN in thirty seconds.\nlet name = \"EXBIN\"\nprint(\"Hello from\", name, EXBIN_VERSION)\n\nfn greet(who) { return \"مرحبا يا \" + who }\nprint(greet(\"عالم\"))\n\nlet langs = [{n: \"Lua\", y: 1993}, {n: \"EXBIN\", y: 2026}, {n: \"Python\", y: 1991}]\nlet by_year = langs.sort(fn(a, b) { return a.y - b.y })\nfor l in by_year { print(format(\"%-8s %d\", l.n, l.y)) }\nprint(\"sum of squares:\", list(range(1, 6)).map(fn(x) { return x * x }).sum())\n"},{"name":"calc.exb","title":"آلة حاسبة (Lexer + Pratt)","code":"// calc.exb — a complete little language (lexer + Pratt parser + evaluator)\n// in about 80 lines, built with EXBIN's own toolkit. Variables, functions,\n// assignment, Arabic identifiers.\nlet pratt = require(\"pratt\")\n\nlet lx = lexer([\n  [\"_\", \"[ \\\\t]+\"],\n  [\"NUM\", \"[0-9]+(\\\\.[0-9]+)?\"],\n  [\"IDENT\", \"[A-Za-z_\\\\x80-\\\\xff][A-Za-z0-9_\\\\x80-\\\\xff]*\"],\n  [\"**\", \"\\\\*\\\\*\"], [\"+\", \"\\\\+\"], [\"-\", \"-\"], [\"*\", \"\\\\*\"], [\"/\", \"/\"], [\"%\", \"%\"],\n  [\"(\", \"\\\\(\"], [\")\", \"\\\\)\"], [\",\", \",\"], [\"=\", \"=\"]\n])\n\nlet spec = {prefix: {}, infix: {}}\nspec.prefix[\"NUM\"] = fn(p, t) { return {type: \"num\", value: num(t.text)} }\nspec.prefix[\"IDENT\"] = fn(p, t) {\n  if p.match(\"(\") {\n    return {type: \"call\", name: t.text, args: pratt.separated(p, \",\", \")\")}\n  }\n  return {type: \"var\", name: t.text}\n}\nspec.prefix[\"(\"] = fn(p, t) {\n  let e = p.parse(0)\n  p.expect(\")\", \"expected ')'\")\n  return e\n}\nspec.prefix[\"-\"] = pratt.unary(30)\nspec.infix[\"=\"] = {prec: 1, fn: fn(p, left, t) {\n  if left.type != \"var\" { p.fail(\"cannot assign to this\") }\n  return {type: \"assign\", name: left.name, value: p.parse(0)}\n}}\nspec.infix[\"+\"] = pratt.binary(10, false)\nspec.infix[\"-\"] = pratt.binary(10, false)\nspec.infix[\"*\"] = pratt.binary(20, false)\nspec.infix[\"/\"] = pratt.binary(20, false)\nspec.infix[\"%\"] = pratt.binary(20, false)\nspec.infix[\"**\"] = pratt.binary(40, true)\n\nlet builtins = {sqrt: sqrt, max: max, min: min, abs: abs, floor: floor, sin: sin, cos: cos}\n\nfn evaluate(n, env) {\n  let t = n.type\n  if t == \"num\" { return n.value }\n  if t == \"var\" {\n    if not env.has(n.name) { error(\"undefined variable '\" + n.name + \"'\") }\n    return env[n.name]\n  }\n  if t == \"assign\" {\n    let v = evaluate(n.value, env)\n    env[n.name] = v\n    return v\n  }\n  if t == \"neg\" or t == \"unary\" { return -evaluate(n.operand, env) }\n  if t == \"call\" {\n    let f = builtins[n.name]\n    if f == nil { error(\"unknown function '\" + n.name + \"'\") }\n    return apply(f, n.args.map(fn(a) { return evaluate(a, env) }))\n  }\n  let a = evaluate(n.left, env)\n  let b = evaluate(n.right, env)\n  if n.op == \"+\" { return a + b }\n  if n.op == \"-\" { return a - b }\n  if n.op == \"*\" { return a * b }\n  if n.op == \"/\" {\n    if b == 0 { error(\"division by zero\") }\n    return a / b\n  }\n  if n.op == \"%\" { return a % b }\n  return a ** b\n}\n\nfn calc(src, env) {\n  let p = pratt.parser(lx.tokenize(src), spec)\n  let ast = p.parse(0)\n  if not p.at_end() { p.fail(\"unexpected input\") }\n  return evaluate(ast, env)\n}\n\nlet env = {}\nlet demo = [\"1 + 2 * 3\", \"x = 10\", \"y = x ** 2 / 4\", \"sqrt(y) + max(1, 2, 3)\",\n            \"(1 + 2) * -3\", \"2 ** 3 ** 2\", \"عدد = 7\", \"عدد * 6\", \"1 / 0\", \"2 +\", \"foo(1)\"]\nlet lines = demo\nif args.len > 1 { lines = args.slice(1) }   // exbin calc.exb \"1+2\" \"x = 3\"\nfor src in lines {\n  let r = pcall(fn() { return calc(src, env) })\n  if r[0] { print(format(\"%-26s => %s\", src, str(r[1]))) }\n  else { print(format(\"%-26s !! %s\", src, str(r[1]))) }\n}\n"},{"name":"json.exb","title":"مفسّر JSON","code":"// json.exb — a JSON parser and pretty-printer written in EXBIN, using the\n// regex-based lexer generator. Handles escapes, \\uXXXX, nesting, Arabic text.\nlet lx = lexer([\n  [\"_\", \"\\\\s+\"],\n  [\"STR\", \"\\\"([^\\\"\\\\\\\\]|\\\\\\\\.)*\\\"\"],\n  [\"NUM\", \"-?[0-9]+(\\\\.[0-9]+)?([eE][-+]?[0-9]+)?\"],\n  [\"WORD\", \"[a-z]+\"],\n  [\"{\", \"\\\\{\"], [\"}\", \"\\\\}\"], [\"[\", \"\\\\[\"], [\"]\", \"\\\\]\"], [\":\", \":\"], [\",\", \",\"]\n])\n\nlet st = {toks: [], pos: 0}\n\nfn peek() { return st.toks[st.pos] }\nfn advance() {\n  let t = st.toks[st.pos]\n  st.pos += 1\n  return t\n}\nfn fail(msg) {\n  let t = peek()\n  error(format(\"JSON error at %d:%d: %s\", t.line, t.col, msg))\n}\nfn expect(type) {\n  if peek().type != type { fail(\"expected '\" + type + \"' but found '\" + peek().text + \"'\") }\n  return advance()\n}\n\nfn unescape(raw) {\n  let body = raw[range(1, raw.len - 1)]\n  let out = \"\"\n  let i = 0\n  while i < body.len {\n    let c = body[i]\n    if c != \"\\\\\" {\n      out += c\n      i += 1\n      continue\n    }\n    let e = body[i + 1]\n    i += 2\n    if e == \"n\" { out += \"\\n\" }\n    else if e == \"t\" { out += \"\\t\" }\n    else if e == \"r\" { out += \"\\r\" }\n    else if e == \"b\" { out += \"\\b\" }\n    else if e == \"f\" { out += \"\\f\" }\n    else if e == \"u\" {\n      out += chr(num(\"0x\" + body[range(i, i + 4)]))\n      i += 4\n    } else { out += e }\n  }\n  return out\n}\n\nfn parse_value() {\n  let t = advance()\n  if t.type == \"STR\" { return unescape(t.text) }\n  if t.type == \"NUM\" { return num(t.text) }\n  if t.type == \"WORD\" {\n    if t.text == \"true\" { return true }\n    if t.text == \"false\" { return false }\n    if t.text == \"null\" { return nil }\n    st.pos -= 1\n    fail(\"unknown word '\" + t.text + \"'\")\n  }\n  if t.type == \"[\" {\n    let items = []\n    if st.toks[st.pos].type == \"]\" {\n      advance()\n      return items\n    }\n    while true {\n      items.push(parse_value())\n      if peek().type == \",\" {\n        advance()\n        continue\n      }\n      expect(\"]\")\n      return items\n    }\n  }\n  if t.type == \"{\" {\n    let obj = {}\n    if peek().type == \"}\" {\n      advance()\n      return obj\n    }\n    while true {\n      let key = unescape(expect(\"STR\").text)\n      expect(\":\")\n      obj[key] = parse_value()\n      if peek().type == \",\" {\n        advance()\n        continue\n      }\n      expect(\"}\")\n      return obj\n    }\n  }\n  st.pos -= 1\n  fail(\"unexpected '\" + t.text + \"'\")\n}\n\nfn parse_json(src) {\n  st.toks = lx.tokenize(src)\n  st.pos = 0\n  let v = parse_value()\n  if peek().type != \"EOF\" { fail(\"trailing data\") }\n  return v\n}\n\nfn quote(s) {\n  let out = \"\\\"\"\n  for c in s {\n    if c == \"\\\"\" { out += \"\\\\\\\"\" }\n    else if c == \"\\\\\" { out += \"\\\\\\\\\" }\n    else if c == \"\\n\" { out += \"\\\\n\" }\n    else if c == \"\\t\" { out += \"\\\\t\" }\n    else { out += c }\n  }\n  return out + \"\\\"\"\n}\n\nfn stringify(v, indent, depth) {\n  let t = type(v)\n  if t == \"nil\" { return \"null\" }\n  if t == \"string\" { return quote(v) }\n  if t == \"number\" or t == \"bool\" { return str(v) }\n  let pad = \"  \".repeat(depth + 1)\n  let end = \"  \".repeat(depth)\n  if t == \"list\" {\n    if v.len == 0 { return \"[]\" }\n    let parts = v.map(fn(x) { return pad + stringify(x, indent, depth + 1) })\n    return \"[\\n\" + parts.join(\",\\n\") + \"\\n\" + end + \"]\"\n  }\n  if v.len == 0 { return \"{}\" }\n  let parts = v.keys().map(fn(k) { return pad + quote(k) + \": \" + stringify(v[k], indent, depth + 1) })\n  return \"{\\n\" + parts.join(\",\\n\") + \"\\n\" + end + \"}\"\n}\n\nlet sample = \"{\\\"name\\\": \\\"EXBIN\\\", \\\"اسم\\\": \\\"لغة\\\", \\\"version\\\": 1.5e0,\n  \\\"tags\\\": [\\\"vm\\\", \\\"tools\\\", true, null], \\\"nested\\\": {\\\"a\\\": [1, 2, {\\\"b\\\": \\\"x\\\\ny\\\"}], \\\"u\\\": \\\"\\\\u0639\\\"}}\"\nlet doc = parse_json(sample)\nprint(stringify(doc, 2, 0))\nprint(\"keys:\", doc.keys())\nprint(\"round-trip equal:\", parse_json(stringify(doc, 2, 0)) == doc)\nlet bad = pcall(fn() { return parse_json(\"{\\\"a\\\": [1, 2,}\") })\nprint(\"error case:\", bad[1])\n"},{"name":"tinylang.exb","title":"لغة صغيرة تُترجم إلى bytecode","code":"// tinylang.exb — \"Tiny\": a small imperative language that COMPILES TO EXBIN\n// BYTECODE with the asm toolkit, runs on the VM, and is saved as a .exbc file.\n//\n//   let n = 10          while cond { ... }        if cond { ... }\n//   x = expr            print expr\nlet pratt = require(\"pratt\")\n\nlet lx = lexer([\n  [\"_\", \"\\\\s+\"], [\"_\", \"#[^\\\\n]*\"],\n  [\"NUM\", \"[0-9]+(\\\\.[0-9]+)?\"],\n  [\"STR\", \"\\\"[^\\\"]*\\\"\"],\n  [\"IDENT\", \"[A-Za-z_\\\\x80-\\\\xff][A-Za-z0-9_\\\\x80-\\\\xff]*\"],\n  [\"==\", \"==\"], [\"!=\", \"!=\"], [\"<=\", \"<=\"], [\">=\", \">=\"],\n  [\"<\", \"<\"], [\">\", \">\"], [\"=\", \"=\"],\n  [\"+\", \"\\\\+\"], [\"-\", \"-\"], [\"*\", \"\\\\*\"], [\"/\", \"/\"], [\"%\", \"%\"],\n  [\"(\", \"\\\\(\"], [\")\", \"\\\\)\"], [\"{\", \"\\\\{\"], [\"}\", \"\\\\}\"]\n], {keywords: {let: \"let\", print: \"print\", while: \"while\", if: \"if\"}})\n\n// ---- parser: expressions via Pratt, statements by recursive descent --------\nlet spec = {prefix: {}, infix: {}}\nspec.prefix[\"NUM\"] = fn(p, t) { return {type: \"num\", value: num(t.text)} }\nspec.prefix[\"STR\"] = fn(p, t) { return {type: \"str\", value: t.text[range(1, t.text.len - 1)]} }\nspec.prefix[\"IDENT\"] = fn(p, t) { return {type: \"var\", name: t.text} }\nspec.prefix[\"(\"] = fn(p, t) {\n  let e = p.parse(0)\n  p.expect(\")\", nil)\n  return e\n}\nspec.prefix[\"-\"] = pratt.unary(30)\nfor op in [\"==\", \"!=\"] { spec.infix[op] = pratt.binary(5, false) }\nfor op in [\"<\", \">\", \"<=\", \">=\"] { spec.infix[op] = pratt.binary(6, false) }\nfor op in [\"+\", \"-\"] { spec.infix[op] = pratt.binary(10, false) }\nfor op in [\"*\", \"/\", \"%\"] { spec.infix[op] = pratt.binary(20, false) }\n\nfn parse_block(p) {\n  let stmts = []\n  while not p.check(\"}\") and not p.at_end() { stmts.push(parse_stmt(p)) }\n  p.expect(\"}\", nil)\n  return stmts\n}\n\nfn parse_stmt(p) {\n  if p.match(\"let\") {\n    let name = p.expect(\"IDENT\", \"expected a name\").text\n    p.expect(\"=\", nil)\n    return {type: \"let\", name: name, value: p.parse(0)}\n  }\n  if p.match(\"print\") { return {type: \"print\", value: p.parse(0)} }\n  if p.match(\"while\") {\n    let cond = p.parse(0)\n    p.expect(\"{\", nil)\n    return {type: \"while\", cond: cond, body: parse_block(p)}\n  }\n  if p.match(\"if\") {\n    let cond = p.parse(0)\n    p.expect(\"{\", nil)\n    return {type: \"if\", cond: cond, body: parse_block(p)}\n  }\n  let name = p.expect(\"IDENT\", \"expected a statement\").text\n  p.expect(\"=\", nil)\n  return {type: \"set\", name: name, value: p.parse(0)}\n}\n\nfn parse(src) {\n  let p = pratt.parser(lx.tokenize(src), spec)\n  let stmts = []\n  while not p.at_end() { stmts.push(parse_stmt(p)) }\n  return stmts\n}\n\n// ---- code generator: AST -> EXBIN bytecode ----------------------------------\nlet BINOPS = {\"+\": \"ADD\", \"-\": \"SUB\", \"*\": \"MUL\", \"/\": \"DIV\", \"%\": \"MOD\", \"<\": \"LESS\",\n              \"<=\": \"LESS_EQUAL\", \">\": \"GREATER\", \">=\": \"GREATER_EQUAL\", \"==\": \"EQUAL\", \"!=\": \"NOT_EQUAL\"}\nlet labels = {n: 0}\nfn fresh(prefix) {\n  labels.n += 1\n  return prefix + str(labels.n)\n}\n\nfn gen_expr(a, n) {\n  let t = n.type\n  if t == \"num\" or t == \"str\" { a.op(\"CONSTANT\", n.value) }\n  else if t == \"var\" { a.op(\"GET_GLOBAL\", n.name) }\n  else if t == \"neg\" or t == \"unary\" {\n    gen_expr(a, n.operand)\n    a.op(\"NEG\")\n  } else {\n    gen_expr(a, n.left)\n    gen_expr(a, n.right)\n    a.op(BINOPS[n.op])\n  }\n}\n\nfn gen_stmts(a, stmts) {\n  for s in stmts { gen_stmt(a, s) }\n}\n\nfn gen_stmt(a, s) {\n  let t = s.type\n  if t == \"let\" {\n    gen_expr(a, s.value)\n    a.op(\"DEFINE_GLOBAL\", s.name)\n  } else if t == \"set\" {\n    gen_expr(a, s.value)\n    a.op(\"SET_GLOBAL\", s.name)\n    a.op(\"POP\")\n  } else if t == \"print\" {\n    a.op(\"GET_GLOBAL\", \"print\")\n    gen_expr(a, s.value)\n    a.op(\"CALL\", 1)\n    a.op(\"POP\")\n  } else if t == \"while\" {\n    let top = fresh(\"top\")\n    let done = fresh(\"done\")\n    a.label(top)\n    gen_expr(a, s.cond)\n    a.op(\"JUMP_IF_FALSE\", done)\n    a.op(\"POP\")\n    gen_stmts(a, s.body)\n    a.op(\"LOOP\", top)\n    a.label(done)\n    a.op(\"POP\")\n  } else if t == \"if\" {\n    let other = fresh(\"else\")\n    let end = fresh(\"end\")\n    gen_expr(a, s.cond)\n    a.op(\"JUMP_IF_FALSE\", other)\n    a.op(\"POP\")\n    gen_stmts(a, s.body)\n    a.op(\"JUMP\", end)\n    a.label(other)\n    a.op(\"POP\")\n    a.label(end)\n  }\n}\n\nfn compile_tiny(src) {\n  let a = asm(\"<tiny>\", 0)\n  gen_stmts(a, parse(src))\n  a.op(\"NIL\").op(\"RETURN\")\n  return a.build()\n}\n\n// ---- demo --------------------------------------------------------------------\nlet program = \"\n# Fibonacci, then a little arithmetic\nlet n = 10\nlet a = 0\nlet b = 1\nwhile n > 0 {\n  print a\n  let t = a + b\n  a = b\n  b = t\n  n = n - 1\n}\nif a > 50 { print \\\"a is big\\\" }\nlet ناتج = (2 + 3) * 4 - 10 / 4\nprint ناتج\n\"\n\nlet main = compile_tiny(program)\nprint(\"compiled:\", fn_info(main).code_size, \"bytes of bytecode\")\nmain()\n\nsave_bytecode(main, \"/tmp/tiny.exbc\")\nprint(\"--- reloaded from /tmp/tiny.exbc ---\")\nload_bytecode(\"/tmp/tiny.exbc\")()\n"}]};
